const body = $input.first().json.body || {};

return [{
  json: {
    company: body.company || 'Customer',
    meeting_title: body.meeting_title || 'Customer meeting',
    meeting_date: body.meeting_date || '',
    meeting_time: body.meeting_time || '',
    meeting_location: body.meeting_location || '',
    meeting_description: body.meeting_description || '',
    industry: body.industry || '',
    country: body.country || ''
  }
}];

const raw = $input.first().json.output;
let brief;

try {
  brief = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (error) {
  throw new Error('Gemini returned invalid JSON: ' + error.message);
}

if (!brief || typeof brief !== 'object' || Array.isArray(brief)) {
  throw new Error('Gemini response must be one JSON object.');
}

const stringFields = [
  'brief_html', 'meeting_priority', 'meeting_readiness_score',
  'opportunity_score', 'risk_level', 'meeting_objective',
  'executive_summary', 'industry', 'headquarters', 'employees',
  'revenue', 'website', 'recommended_pitch', 'objection_handling'
];
const arrayFields = [
  'key_products', 'latest_news', 'competitors', 'customer_pain_points',
  'discovery_questions', 'talking_points', 'cross_sell_opportunities',
  'meeting_preparation', 'documents', 'follow_up', 'next_steps'
];
const missing = [
  ...stringFields.filter((key) => typeof brief[key] !== 'string' || !brief[key].trim()),
  ...arrayFields.filter((key) => !Array.isArray(brief[key]))
];

if (missing.length) {
  throw new Error('Gemini response violates the briefing schema. Invalid fields: ' + missing.join(', '));
}

const request = $('Normalize Brief Request').first().json;
return [{
  json: {
    status: 'completed',
    company: request.company,
    customer_name: request.company,
    meeting_title: request.meeting_title,
    generated_at: new Date().toISOString(),
    email_status: 'not_requested',
    ...brief
  }
}];
